    type: character
    zone: field
    display:
      kind: 防壁

    unitCondition:
      cards:
        count: 1
      face: down

    properties:
      characterType: bulwark
      labels: [defense]

    text:
      summary: 任意のカード1枚を裏向きにしたユニットは防壁として扱う。
